// Studio chrome, drawn in the Graphite theme (theme/graphite.css.ts,
// generated by the ui token resolver): no chroma, a narrow tonal range, no
// shadows, Aspekta throughout. Only the chrome wears it. The stage keeps the
// film's own look, so what you tune is what renders.
//
// DialKit draws the panel and the dock. Its look is a set of `--dial-*`
// variables; below they are bound to `--ui-*` tokens, so the panel and the dock
// are the same material as the rest of the studio and follow the same scheme.
import { GRAPHITE_CSS } from './theme/graphite.css.ts';
import aspekta from './theme/fonts/AspektaVF.woff2';

const DIALKIT = `
.ms .dialkit-root, .ms .dialkit-root[data-theme] {
  --dial-surface: var(--ui-bg-muted);
  --dial-surface-hover: var(--ui-bg-hover);
  --dial-surface-active: var(--ui-bg-active);
  --dial-surface-subtle: var(--ui-bg-sunken);
  --dial-text-root: var(--ui-text-primary);
  --dial-text-section: var(--ui-text-secondary);
  --dial-text-label: var(--ui-text-muted);
  --dial-text-focus: var(--ui-text-primary);
  --dial-text-primary: var(--ui-text-primary);
  --dial-text-secondary: var(--ui-text-muted);
  --dial-text-tertiary: var(--ui-text-disabled);
  --dial-border: var(--ui-border-subtle);
  --dial-border-hover: var(--ui-border-default);
  --dial-focus-ring: var(--ui-focus-ring-color);
  --dial-glass-bg: var(--ui-bg-surface);
  --dial-dropdown-bg: var(--ui-bg-elevated);
  --dial-backdrop-blur: 0px;
  --dial-radius: var(--ui-radius-sm);
  --dial-row-height: var(--ui-control-md-height, 32px);
  --dial-row-gap: 4px;
  --dial-shadow: none;
  --dial-shadow-collapsed: none;
  --dial-shadow-dropdown: var(--ui-shadow-md, none);
  --dial-timeline-clip-overlay: transparent;
  font-family: var(--ui-font-body);
  font-feature-settings: "tnum";
}
/* DialKit sets numbers in Geist Mono. The system has one face; figures align with tabular numerals instead. */
.ms .dialkit-root :is(.dialkit-slider-value, .dialkit-slider-input, .dialkit-pad-value, .dialkit-color-css-input, .dialkit-timeline-time, .dialkit-timeline-clip-duration, .dialkit-shortcuts-row-key) {
  font-family: var(--ui-font-body); font-variant-numeric: tabular-nums;
}
.ms .dialkit-panel-inner, .ms .dialkit-timeline-dock { border-radius: var(--ui-radius-md); }
.ms .dialkit-panel-inner { border: 0; background: transparent; padding: 8px 10px; }
.ms .dialkit-spring-viz line { stroke: var(--ui-border-subtle); }
.ms .dialkit-spring-viz line[stroke-dasharray] { stroke: var(--ui-border-default); stroke-dasharray: none; }
.ms .dialkit-spring-viz path { stroke: var(--ui-text-muted); }
.ms .dialkit-toggle-thumb { box-shadow: 0 0 0 1px var(--ui-border-subtle); }
/* Clips: one quiet tone with a hairline edge; the scene under the playhead is solid
   ink. The length sits at the clip's start, where the playhead rarely is when you read it. */
.ms .dialkit-timeline-clip { top: 4px; bottom: 4px; justify-content: flex-start; padding: 0 10px; border-radius: 5px; background: var(--ui-bg-active) !important; color: var(--ui-text-primary); box-shadow: inset 0 0 0 1px var(--ui-border-subtle); transition: background-color var(--ui-motion-micro); }
.ms .dialkit-timeline-clip:hover { background: var(--ui-bg-selected) !important; }
.ms .dialkit-timeline-clip[data-current] { background: var(--ui-bg-inverse) !important; color: var(--ui-text-inverse); box-shadow: none; }
.ms .dialkit-timeline-clip[data-selected] { box-shadow: 0 0 0 2px var(--ui-border-focus); }
.ms .dialkit-timeline-clip-duration { color: var(--ui-text-muted); font-size: var(--ui-text-caption); font-weight: 500; }
.ms .dialkit-timeline-clip[data-current] .dialkit-timeline-clip-duration { color: var(--ui-text-inverse); opacity: 0.7; }
.ms .dialkit-timeline-clip-ghost { background: var(--ui-bg-muted) !important; }
`;

export const STUDIO_CSS = `
@font-face { font-family: "Aspekta"; font-weight: 100 900; font-style: normal; font-display: swap; src: url("${aspekta}") format("woff2"); }
${GRAPHITE_CSS}
/* The page: one screen, no page scroll. Its ground is Graphite's bg-base,
   written out because the theme scope sits on the chrome only: the stage must
   not inherit it. */
html:has(.ms), body:has(.ms) { margin: 0; height: 100%; overflow: hidden; }
.ms {
  color-scheme: light dark;
  box-sizing: border-box; height: 100vh; height: 100dvh; margin: 0;
  display: grid; grid-template-rows: minmax(0, 1fr) auto;
  /* Raw values on purpose: the Graphite tokens are scoped to .ms-chrome so the stage
     never inherits them, and the page ground, the letterbox and the banner sit outside it. */
  background: light-dark(#F3F3F2, #1E1E1E);
}
.ms-chrome {
  --s-bg: var(--ui-bg-base);
  --s-panel: var(--ui-bg-surface);
  --s-fill: var(--ui-bg-muted);
  --s-ink: var(--ui-text-primary);
  --s-muted: var(--ui-text-muted);
  --s-line: var(--ui-border-subtle);
  /* Rule 5: images hold their edge with pure black or white, never a tinted neutral. */
  --s-outline: light-dark(rgb(0 0 0 / 0.1), rgb(255 255 255 / 0.1));
  --s-outline-hover: light-dark(rgb(0 0 0 / 0.22), rgb(255 255 255 / 0.22));
  --s-warn: var(--ui-intent-warning-fg);
  --s-bad: var(--ui-intent-danger-fg);
  color: var(--s-ink);
  font-family: var(--ui-font-body); font-size: var(--ui-text-body-sm); line-height: var(--ui-leading-normal);
  font-weight: var(--ui-text-body-sm-weight); letter-spacing: var(--ui-text-body-sm-tracking);
  -webkit-font-smoothing: antialiased;
}
.ms *, .ms *::before, .ms *::after { box-sizing: border-box; }
/* :where keeps these resets at zero specificity, so every component rule below wins. */
:where(.ms) :where(button, input, textarea) { font: inherit; letter-spacing: inherit; color: inherit; }
:where(.ms) button { cursor: pointer; }
.ms :focus-visible { outline: var(--ui-focus-ring-width) solid var(--ui-focus-ring-color); outline-offset: 2px; }
.ms ::selection { background: var(--ui-selection-bg); color: var(--ui-selection-fg); }
.ms [hidden] { display: none !important; }

/* No page-wide bar. Each column heads itself at one height, so the three heads
   (scenes, the film, the inspector's tabs) share one baseline and one rule. */
.ms { --ms-head: 48px; }
.ms-head { display: flex; align-items: center; gap: 16px; height: var(--ms-head); padding: 0 22px; border-bottom: var(--ui-stroke-default) solid var(--s-line); }
.ms-film { display: flex; align-items: center; gap: 14px; min-width: 0; flex: 1; }
.ms-film h1 { margin: 0; font-size: var(--ui-text-label-md); font-weight: 600; letter-spacing: var(--ui-tracking-tight); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.ms-meta { display: flex; align-items: center; margin: 0; color: var(--s-muted); font-size: var(--ui-text-caption); font-variant-numeric: tabular-nums; white-space: nowrap; }
.ms-meta span + span::before { content: ""; display: inline-block; width: 3px; height: 3px; margin: 0 8px; border-radius: 50%; background: currentColor; opacity: 0.6; vertical-align: middle; }
.ms-status { margin: 0; display: inline-flex; align-items: center; gap: 8px; min-height: 28px; padding: 0 12px; border-radius: var(--ui-radius-full); box-shadow: inset 0 0 0 1px var(--s-line); color: var(--ui-text-secondary); font-size: var(--ui-text-caption); font-variant-numeric: tabular-nums; white-space: nowrap; }
.ms-status:empty { display: none; }
.ms-status::before { content: ""; width: 6px; height: 6px; border-radius: 50%; background: var(--s-muted); }
.ms-status[data-state="saving"]::before { background: var(--ui-intent-warning-fg); }
.ms-status[data-state="error"] { color: var(--s-bad); }
.ms-status[data-state="error"]::before { background: var(--s-bad); }

/* Three columns: scenes, stage, inspector. */
.ms-body { display: grid; grid-template-columns: 240px minmax(0, 1fr) 360px; min-height: 0; }

/* A scrolling region and its edge fades (fade.ts, ui's Fade): the region scrolls,
   this box holds it still and positions the bands. */
.ms-scroll { position: relative; flex: 1; min-height: 0; display: flex; flex-direction: column; overflow: hidden; }

/* Scenes: a still of each, numbered in the gutter. The scene under the playhead
   gets a ring and a bar showing how far into it the playhead is. */
.ms-rail { display: flex; flex-direction: column; min-height: 0; border-right: var(--ui-stroke-default) solid var(--s-line); }
.ms-rail-head { flex: none; display: flex; align-items: center; gap: 8px; height: var(--ms-head); padding: 0 22px; border-bottom: var(--ui-stroke-default) solid var(--s-line); }
.ms-rail h2 { margin: 0; font-size: var(--ui-text-label-md); font-weight: 600; letter-spacing: var(--ui-tracking-tight); }
.ms-rail-count { color: var(--s-muted); font-size: var(--ui-text-caption); font-variant-numeric: tabular-nums; }
.ms-scenes { flex: 1; min-height: 0; list-style: none; margin: 0; padding: 12px 12px 16px; display: grid; align-content: start; gap: 4px; overflow-y: auto; scrollbar-width: thin; scrollbar-color: var(--ui-border-default) transparent; }
.ms-scenes button {
  display: grid; gap: 10px; width: 100%; padding: 8px 8px 12px;
  border: 0; border-radius: var(--ui-radius-lg); background: none; text-align: left;
  transition: background-color var(--ui-motion-micro);
}
.ms-scenes button:hover { background: var(--ui-bg-hover); }
.ms-thumb { position: relative; display: block; aspect-ratio: var(--ar, 1.7778); border-radius: var(--ui-radius-sm); overflow: hidden; background: var(--ui-bg-muted); box-shadow: 0 0 0 1px var(--s-outline); transition: box-shadow var(--ui-motion-micro); }
.ms-thumb > .m-stage { position: absolute; left: 0; top: 0; pointer-events: none; }
.ms-scenes button:hover .ms-thumb { box-shadow: 0 0 0 1px var(--s-outline-hover); }
.ms-scenes button[aria-current] .ms-thumb { box-shadow: 0 0 0 2px var(--s-ink); }
.ms-scene-text { padding: 0 2px; display: grid; gap: 2px; min-width: 0; }
.ms-scene-head { display: flex; align-items: baseline; gap: 8px; min-width: 0; }
.ms-scene-head b { font-weight: 600; color: var(--ui-text-secondary); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.ms-scenes button[aria-current] .ms-scene-head b { color: var(--s-ink); }
.ms-scene-len { margin-left: auto; color: var(--s-muted); font-variant-numeric: tabular-nums; font-size: var(--ui-text-caption); }
.ms-scene-intent { color: var(--s-muted); font-size: var(--ui-text-caption); line-height: 1.4; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }

/* Stage: the largest frame that fits, on the page ground. */
.ms-canvas { display: grid; grid-template-rows: auto minmax(0, 1fr) auto; min-width: 0; min-height: 0; }
.ms-stagewrap { margin: 20px 20px 0; }
.ms-stagewrap { position: relative; container-type: size; display: grid; place-items: center; min-height: 0; }
.ms-frame { width: min(100cqw, 100cqh * var(--ar, 1.7778)); background: light-dark(#E7E7E6, #181818); border-radius: 12px; overflow: hidden; }
.ms-host { width: 100%; }
.ms-banner { position: absolute; left: 50%; top: 16px; translate: -50% 0; max-width: 90%; padding: 10px 14px; border-radius: var(--ui-radius-md); background: light-dark(#e9dbd4, #31231e); color: light-dark(#a6411b, #d96f4b); font: 500 13px/1.4 Aspekta, system-ui, sans-serif; }

/* Transport: time on the left, controls in the middle, where on the right. */
.ms-transport { display: grid; grid-template-columns: 1fr auto 1fr; align-items: center; gap: 16px; padding: 14px 20px 16px; }
.ms-clock { margin: 0; color: var(--s-muted); font-variant-numeric: tabular-nums; }
.ms-clock b { color: var(--s-ink); font-weight: 600; }
.ms-where { margin: 0; justify-self: end; color: var(--s-muted); font-variant-numeric: tabular-nums; text-align: right; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 100%; }
.ms-controls { display: flex; align-items: center; gap: 10px; }
.ms-controls svg { width: 20px; height: 20px; display: block; }
.ms-skip { display: grid; place-items: center; width: 36px; height: 36px; border: 0; border-radius: var(--ui-radius-full); background: none; color: var(--ui-text-secondary); }
.ms-skip:hover { background: var(--ui-bg-hover); color: var(--s-ink); }
.ms-play { display: grid; place-items: center; width: 44px; height: 44px; border: 0; border-radius: var(--ui-radius-full); background: var(--s-ink); color: var(--ui-text-inverse); transition: transform var(--ui-motion-micro); }
.ms-play:hover { background: var(--ui-bg-inverse-hover); }
.ms-play:active { transform: scale(var(--ui-press-scale)); }
.ms-play svg { width: 20px; height: 20px; }

/* Inspector: a flat column on the page ground, split from the stage by one
   hairline (the scene list's, mirrored). No card inside it: every line in the
   column is drawn once, by one owner: the tab bar's rule, then DialKit's groups. */
.ms-inspector { display: flex; flex-direction: column; min-height: 0; border-left: var(--ui-stroke-default) solid var(--s-line); }
.ms-tabs { flex: none; display: flex; align-items: center; gap: 4px; height: var(--ms-head); padding: 0 14px; border-bottom: var(--ui-stroke-default) solid var(--s-line); }
.ms-tabs button { display: inline-flex; align-items: center; gap: 6px; min-height: 28px; padding: 0 8px; border: 0; border-radius: var(--ui-radius-md); background: none; color: var(--s-muted); font-weight: 600; transition: background-color var(--ui-motion-micro), color var(--ui-motion-micro); }
.ms-tabs button:hover { color: var(--ui-text-secondary); }
.ms-tabs button[aria-selected="true"] { background: var(--ui-bg-selected); color: var(--s-ink); }
.ms-tabs button:focus-visible { outline-offset: 2px; }
.ms-count { min-width: 16px; min-height: 16px; padding: 0 4px; border-radius: var(--ui-radius-full); background: var(--ui-bg-elevated); color: var(--s-ink); font-size: var(--ui-text-label-sm); font-weight: 600; line-height: 16px; text-align: center; font-variant-numeric: tabular-nums; }
.ms-panel, .ms-notes, .ms-problems { flex: 1; min-height: 0; overflow-y: auto; scrollbar-width: thin; scrollbar-color: var(--ui-border-default) transparent; }
.ms-notes, .ms-problems { padding: 16px 20px 20px; }
.ms-empty { margin: 6px 4px; color: var(--s-muted); list-style: none; }

/* The Tune panel: DialKit, inline, on the column's ground. DialKit draws a top and
   a bottom border on every folder and a rule under its header, so neighbouring and
   nested folders stack into double lines. Here: no folder borders at all, a
   gap between top-level groups (ui-craft 21: group with space, not lines), and under the pinned header the edge fade
   instead of a rule (it only shows once something has scrolled under it). */
.ms .ms-panel .dialkit-root, .ms .ms-panel .dialkit-root[data-theme] { --dial-glass-bg: var(--ui-bg-base); }
.ms .ms-panel .dialkit-panel-inner { padding: 0 20px 20px; border-radius: 0; }
.ms-panel .dialkit-panel-header { padding: 16px 0 8px; margin: 0; border-bottom: 0; background: var(--ui-bg-base); }
.ms-panel .dialkit-folder:not(.dialkit-folder-root) { border-top: 0 !important; border-bottom: 0 !important; margin: 0 !important; }
.ms-panel .dialkit-folder-root > .dialkit-folder-content > .dialkit-folder-inner { gap: 0; }
.ms-panel .dialkit-folder-root > .dialkit-folder-content > .dialkit-folder-inner > .dialkit-folder { padding: 6px 0; }
.ms-panel .dialkit-folder-root > .dialkit-folder-content > .dialkit-folder-inner > .dialkit-folder + .dialkit-folder { margin-top: 12px !important; }
.ms-panel .dialkit-folder .dialkit-folder-inner { gap: 4px; }

/* Notes: a composer, then the list. The composer's states are drawn on its own
   border, inside the box: the pane scrolls, and a ring outside would be clipped. */
.ms-notes { display: flex; flex-direction: column; gap: 12px; }
.ms-composer { flex: none; padding: 10px 10px 10px 12px; border: var(--ui-stroke-default) solid var(--s-line); border-radius: var(--ui-radius-lg); background: var(--ui-bg-elevated); transition: border-color var(--ui-motion-micro); }
.ms-composer:hover { border-color: var(--ui-border-default); }
.ms-composer:focus-within { border-color: var(--ui-border-focus); }
.ms-composer textarea { display: block; width: 100%; padding: 2px 0 10px; border: 0; background: none; resize: none; line-height: 1.45; }
.ms-composer textarea::placeholder { color: var(--ui-text-placeholder); }
.ms-composer textarea:focus-visible { outline: none; }
.ms-composer-foot { display: flex; align-items: center; justify-content: space-between; gap: 8px; }
.ms-composer-foot small { color: var(--s-muted); font-size: var(--ui-text-caption); }
.ms-primary { min-height: 32px; padding: 0 14px; border: 0; border-radius: var(--ui-radius-full); background: var(--s-ink); color: var(--ui-text-inverse); font-weight: 600; font-variant-numeric: tabular-nums; white-space: nowrap; }
.ms-primary:hover { background: var(--ui-bg-inverse-hover); }
.ms-secondary { min-height: 28px; padding: 0 12px; border: var(--ui-stroke-default) solid var(--s-line); border-radius: var(--ui-radius-full); background: var(--ui-bg-elevated); font-weight: 600; }
.ms-note-list { list-style: none; margin: 0; padding: 0; display: grid; gap: 2px; }
.ms-note-list > .ms-empty { margin: 0 12px; }
.ms-note-list > li:not(.ms-empty) { display: grid; grid-template-columns: auto minmax(0, 1fr) auto; gap: 10px; align-items: start; padding: 10px; border-radius: var(--ui-radius-md); }
.ms-note-list > li:not(.ms-empty):hover { background: var(--ui-bg-hover); }
.ms-note-list input[type="checkbox"] { margin: 3px 0 0; accent-color: var(--s-ink); }
.ms-note-meta { display: flex; gap: 8px; align-items: baseline; color: var(--s-muted); font-size: var(--ui-text-caption); }
.ms-note-list p { margin: 3px 0 0; overflow-wrap: anywhere; }
.ms-note-list li[data-status="done"] p { color: var(--s-muted); text-decoration: line-through; }
.ms-note-list .ms-reply { text-decoration: none !important; font-style: italic; color: var(--ui-text-secondary); }
.ms-jump { border: 0; background: none; padding: 0; color: var(--s-ink); font-weight: 600; font-variant-numeric: tabular-nums; text-decoration: underline; text-decoration-color: var(--s-line); text-underline-offset: 3px; }
.ms-jump:hover { text-decoration-color: currentColor; }
.ms-del { border: 0; background: none; color: var(--s-muted); font-size: 18px; line-height: 1; min-width: 24px; min-height: 24px; border-radius: var(--ui-radius-sm); opacity: 0; transition: opacity var(--ui-motion-micro); }
.ms-note-list li:hover .ms-del, .ms-del:focus-visible { opacity: 1; }
.ms-del:hover { color: var(--s-ink); background: var(--ui-bg-active); }
@media (hover: none) { .ms-del { opacity: 1; } }

/* Issues. */
.ms-problems ul { list-style: none; margin: 0; padding: 0; display: grid; gap: 8px; }
.ms-problems li { display: grid; gap: 4px; padding: 10px 12px; border-radius: var(--ui-radius-md); background: var(--s-fill); }
.ms-problems li p { margin: 0; }
.ms-problems code { font: inherit; font-weight: 600; overflow-wrap: anywhere; }
.ms-level { font-size: var(--ui-text-caption); font-weight: 600; }
.ms-problems li[data-level="error"] .ms-level { color: var(--s-bad); }
.ms-problems li[data-level="warning"] .ms-level { color: var(--s-warn); }
.ms-problems li .ms-secondary { justify-self: start; margin-top: 4px; }

/* Dock along the bottom, as wide as the screen. DialKit draws it; its own play
   and replay buttons are hidden because the transport above owns playback. */
.ms-dock { position: relative; min-width: 0; overflow: hidden; }
.ms-dock-scroll { max-height: 40vh; overflow-y: auto; padding: 0 16px 16px; scrollbar-width: thin; scrollbar-color: var(--ui-border-default) transparent; }
.ms-dock .dialkit-timeline { position: static; }
.ms .ms-dock .dialkit-timeline-dock { max-height: none !important; padding: 0 16px 14px; gap: 8px; border-color: var(--s-line); border-radius: var(--ui-radius-lg); background: var(--ui-bg-surface); }
.ms-dock .dialkit-timeline-actions > button[aria-label$=" timeline"]:not(.dialkit-timeline-chevron) { display: none; }
/* Rows: the header and the scene names share one left edge; lanes are sunk, clips sit on them. */
.ms-dock .dialkit-timeline-section { --dial-timeline-label-w: 112px; --dial-timeline-header-h: 48px; }
.ms-dock .dialkit-timeline-header { padding: 6px 0 0; }
.ms-dock .dialkit-timeline-title { font-size: var(--ui-text-label-md); font-weight: 600; letter-spacing: var(--ui-tracking-tight); }
.ms-dock .dialkit-timeline-grid { gap: 4px; }
.ms-dock .dialkit-timeline-row:not(.dialkit-timeline-ruler-row) { height: 32px; }
.ms-dock .dialkit-timeline-label { font-size: var(--ui-text-body-sm); color: var(--ui-text-secondary); }
.ms-dock .dialkit-timeline-lane { border-radius: var(--ui-radius-md); }

/* Narrower screens: the scene list folds away first, then everything stacks and the page scrolls. */
@media (max-width: 1180px) {
  .ms-body { grid-template-columns: minmax(0, 1fr) 340px; } .ms-rail { display: none; }
}
@media (max-width: 820px) {
  html:has(.ms), body:has(.ms) { height: auto; overflow: auto; }
  .ms { height: auto; display: block; }
  .ms-head { padding: 0 16px; } .ms-stagewrap { margin: 16px 12px 0; }
  .ms-meta { display: none; }
  .ms-dock .dialkit-timeline-section { --dial-timeline-label-w: 76px; }
  .ms-body { display: block; }
  .ms-stagewrap { container-type: inline-size; }
  .ms-frame { width: 100%; }
  .ms-inspector { border-left: 0; border-top: var(--ui-stroke-default) solid var(--s-line); }
  .ms-tabs { padding: 0 8px; } .ms .ms-panel .dialkit-panel-inner { padding: 0 16px 16px; } .ms-notes, .ms-problems { padding: 16px; }
  .ms-panel, .ms-notes, .ms-problems { max-height: 70vh; }
  .ms-dock-scroll { max-height: none; }
  /* Phone: the controls centred under the stage, time and place on one line below them. */
  .ms-transport { grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); row-gap: 10px; padding: 14px 12px 16px; }
  .ms-controls { order: -1; grid-column: 1 / -1; justify-self: center; gap: 16px; }
  .ms-clock { justify-self: start; } .ms-where { justify-self: end; }
}
${DIALKIT}
html.render, html.render body { margin: 0; background: #000; overflow: hidden; }
`;
